-- =====================================================================
--  BLOC E - VERIFICATION
--  Attendu : 2 grille(s), 6 sujet(s), 30 etalon(s), 2 gabarit(s),
--  et AUCUN sujet a moins de 3 etalons.
-- =====================================================================

select 'grilles' as objet, count(*) as n from public.rubrics where matiere = 'philosophie'
union all select 'sujets', count(*) from public.subject_cards where matiere = 'philosophie'
union all select 'etalons', count(*) from public.benchmark_cards b
  join public.subject_cards s on s.id = b.subject_id where s.matiere = 'philosophie'
union all select 'gabarits', count(*) from public.dossier_templates where matiere = 'philosophie';

select s.id, s.exercise_type, s.status, count(b.id) as etalons
from public.subject_cards s
left join public.benchmark_cards b on b.subject_id = s.id
where s.matiere = 'philosophie'
group by s.id, s.exercise_type, s.status
order by s.id;
